# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FRANSIZ İHTİLALİ\'NİN (1789) TEMEL NEDENLERİ VE TOPLUMSAL YAPI</text>\n  <rect x="20" y="44" width="320" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">1. İhtilalin Dört Temel Nedeni</text>\n  <text x="32" y="92" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">Siyasi Neden:</tspan> Kral XVI. Louis\'nin baskıcı</text>\n  <text x="40" y="107" font-size="10" fill="#475569">mutlak monarşi yönetimi ve hukuksuzluk.</text>\n  <text x="32" y="129" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">Sosyal Neden:</tspan> Ayrıcalıklı sınıflar (soylular,</text>\n  <text x="40" y="144" font-size="10" fill="#475569">rahipler) ile halk arasındaki derin eşitsizlik.</text>\n  <text x="32" y="166" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">Ekonomik Neden:</tspan> Savaşlar ve saray israfı</text>\n  <text x="40" y="181" font-size="10" fill="#475569">yüzünden ağır vergiler ve mali iflas.</text>\n  <text x="32" y="203" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">Fikrî Neden:</tspan> Montesquieu, Rousseau ve</text>\n  <text x="40" y="218" font-size="10" fill="#475569">Voltaire gibi Aydınlanma düşünürlerinin etkisi.</text>\n\n  <rect x="360" y="44" width="320" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">2. 1789 Öncesi Fransız Toplumsal Piramidi</text>\n  <polygon points="520,78 465,115 575,115" fill="#fecaca" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="520" y="108" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#991b1b">1. Rahipler (Vergi Yok)</text>\n\n  <polygon points="462,119 425,158 615,158 578,119" fill="#fde68a" stroke="#d97706" stroke-width="1.8"/>\n  <text x="520" y="143" text-anchor="middle" font-size="10" font-weight="bold" fill="#92400e">2. Soylular / Aristokratlar (Vergi Yok)</text>\n\n  <polygon points="422,162 380,210 660,210 618,162" fill="#bbf7d0" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="520" y="183" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">3. Üçüncü Sınıf / Tiers-État (%98)</text>\n  <text x="520" y="199" text-anchor="middle" font-size="9.5" fill="#14532d">Burjuvalar, Köylüler, İşçiler (Tüm Vergiyi Öder!)</text>\n  <text x="520" y="226" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">İhtilali başlatan itici güç: Burjuvazi ve Halk</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">14 TEMMUZ 1789 BASTILLE BASKINI VE EVRENSEL İHTİLAL İLKELERİ</text>\n  <rect x="20" y="44" width="210" height="194" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">1. İhtilalin Dönüm Noktaları</text>\n  <text x="32" y="92" font-size="10" fill="#334155">• <tspan font-weight="bold">Mayıs 1789:</tspan> États-Généraux\'nun</text>\n  <text x="40" y="107" font-size="9.5" fill="#334155">toplanması ve Ulusal Meclis ilanı.</text>\n  <text x="32" y="129" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">14 Temmuz 1789:</tspan> Bastille</text>\n  <text x="40" y="144" font-size="9.5" fill="#334155">Hapishanesi\'nin basılması.</text>\n  <text x="32" y="166" font-size="10" fill="#334155">• <tspan font-weight="bold">26 Ağustos 1789:</tspan> İnsan ve</text>\n  <text x="40" y="181" font-size="9.5" fill="#334155">Yurttaş Hakları Bildirisi.</text>\n  <text x="32" y="203" font-size="10" fill="#334155">• <tspan font-weight="bold">1791-1792:</tspan> Anayasa ve</text>\n  <text x="40" y="218" font-size="9.5" fill="#334155">Cumhuriyetin ilan edilmesi.</text>\n\n  <rect x="245" y="44" width="210" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. İnsan ve Yurttaş Hakları</text>\n  <rect x="259" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Özgürlük · Eşitlik · Kardeşlik</text>\n  <text x="257" y="128" font-size="10" fill="#334155">• İnsanlar özgür ve kanun önünde</text>\n  <text x="265" y="143" font-size="10" fill="#334155">haklar bakımından eşit doğar.</text>\n  <text x="257" y="165" font-size="10" fill="#334155">• Egemenliğin kaynağı kral değil</text>\n  <text x="265" y="180" font-size="10" font-weight="bold" fill="#1e40af">doğrudan ulustur (millettir).</text>\n  <text x="257" y="202" font-size="10" fill="#334155">• Mülkiyet hakkı, kişi güvenliği ve</text>\n  <text x="265" y="217" font-size="10" fill="#334155">ifade özgürlüğü güvencededir.</text>\n\n  <rect x="470" y="44" width="210" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. Doğurduğu Evrensel Akımlar</text>\n  <rect x="484" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Ulus-Devlet ve Anayasalcılık</text>\n  <text x="482" y="128" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Milliyetçilik:</tspan> Her ulusun kendi</text>\n  <text x="490" y="143" font-size="10" fill="#334155">bağımsız devletini kurma ideali.</text>\n  <text x="482" y="165" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Meşrutiyet / Demokrasi:</tspan></text>\n  <text x="490" y="180" font-size="10" fill="#334155">Mutlak krallıkların yıkılması.</text>\n  <text x="482" y="202" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Laik Hukuk:</tspan> Din ve vicdan</text>\n  <text x="490" y="217" font-size="10" fill="#334155">hürriyetinin anayasal teminatı.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FRANSIZ İHTİLALİ\'NİN OSMANLI DEVLETİ ÜZERİNDEKİ İKİ YÖNLÜ ETKİSİ</text>\n  <rect x="20" y="44" width="320" height="194" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">1. Olumsuz Etkisi: Milliyetçilik İsyanları</text>\n  <rect x="34" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">Çok Uluslu Yapının ve Millet Sisteminin Sarsılması</text>\n  <text x="34" y="128" font-size="10" fill="#334155">• Balkanlar\'daki gayrimüslim azınlıklar arasında</text>\n  <text x="42" y="143" font-size="10" fill="#334155">bağımsızlık amaçlı milliyetçilik ayaklanmaları çıktı.</text>\n  <text x="34" y="165" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">İlk İsyan Eden:</tspan> Sırplar (1804 - Kara Yorgi)</text>\n  <text x="34" y="185" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">İlk Bağımsız Olan:</tspan> Yunanlılar (1829 Edirne Ant.)</text>\n  <text x="34" y="205" font-size="10" fill="#334155">• Avrupalı devletler "Azınlık Hakları" bahanesiyle</text>\n  <text x="42" y="220" font-size="10" fill="#334155">Osmanlı Devleti\'nin iç işlerine müdahale etti.</text>\n\n  <rect x="360" y="44" width="320" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Olumlu Etkisi: Demokratikleşme ve Hukuk</text>\n  <rect x="374" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Kanun Üstünlüğü, Eşitlik ve Anayasal Düzen</text>\n  <text x="374" y="128" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Tanzimat Fermanı (1839):</tspan> Kanun üstünlüğü,</text>\n  <text x="382" y="143" font-size="10" fill="#334155">can, mal ve ırz güvenliği, adil vergi ilkesi.</text>\n  <text x="374" y="165" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Islahat Fermanı (1856):</tspan> Müslüman ve gayrimüslim</text>\n  <text x="382" y="180" font-size="10" fill="#334155">tebaa arasında tam hukuki eşitlik çabası.</text>\n  <text x="374" y="202" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Kanun-ı Esasi ve Meşrutiyet (1876 / 1908):</tspan></text>\n  <text x="382" y="217" font-size="10" fill="#334155">Anayasal ve parlamentolu yönetime geçiş.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
